@push('scripts')<script>(()=>{const form=document.querySelector('[data-partner-form]');if(!form)return;const error=form.querySelector('[data-partner-error]'),success=form.querySelector('[data-partner-success]'),button=form.querySelector('button[type=submit]');form.querySelectorAll('input,textarea').forEach(input=>input.addEventListener('input',()=>{input.closest('label')?.classList.remove('is-invalid');error.classList.add('d-none');}));form.addEventListener('submit',async e=>{e.preventDefault();let invalid=form.querySelector(':invalid');if(invalid){invalid.closest('label')?.classList.add('is-invalid');invalid.focus();error.textContent='Please complete the highlighted information.';error.classList.remove('d-none');return;}button.disabled=true;try{const response=await fetch(form.action,{method:'POST',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:new FormData(form)}),body=await response.json();if(!response.ok)throw new Error(Object.values(body.errors||{}).flat()[0]||body.message);form.reset();success.textContent=body.message;success.classList.remove('d-none');success.scrollIntoView({behavior:'smooth',block:'center'});}catch(ex){error.textContent=ex.message||'Your application could not be sent.';error.classList.remove('d-none');}finally{button.disabled=false;}});})();</script>@endpush
